#define WORD_BREAK_MAX 4096

static char **g_res;
static int g_count;

static void wb_dfs(char *s, int n, char **dict, int dictSize, int pos, char *buf, int blen) {
  if (pos == n) {
    buf[blen] = '\0';
    g_res[g_count] = (char *)malloc(blen + 1);
    strcpy(g_res[g_count], buf);
    g_count++;
    return;
  }
  for (int i = 0; i < dictSize; i++) {
    int len = (int)strlen(dict[i]);
    if (pos + len <= n && strncmp(s + pos, dict[i], len) == 0) {
      int old = blen;
      if (blen > 0) {
        buf[blen++] = ' ';
      }
      memcpy(buf + blen, dict[i], len);
      blen += len;
      wb_dfs(s, n, dict, dictSize, pos + len, buf, blen);
      blen = old;
    }
  }
}

char **wordBreak(char *s, char **wordDict, int wordDictSize, int *returnSize) {
  int n = (int)strlen(s);
  g_res = (char **)malloc(sizeof(char *) * WORD_BREAK_MAX);
  g_count = 0;
  char *buf = (char *)malloc(n * 2 + 2);
  wb_dfs(s, n, wordDict, wordDictSize, 0, buf, 0);
  free(buf);
  *returnSize = g_count;
  return g_res;
}

class Solution {
public:
  vector<string> wordBreak(string s, vector<string> &wordDict) {
    unordered_set<string> dict(wordDict.begin(), wordDict.end());
    unordered_map<int, vector<string>> memo;
    function<vector<string>(int)> dfs = [&](int start) -> vector<string> {
      if (memo.count(start)) return memo[start];
      if (start == (int)s.size()) return vector<string>{""};
      vector<string> res;
      for (int end = start + 1; end <= (int)s.size(); end++) {
        string w = s.substr(start, end - start);
        if (dict.count(w)) {
          for (auto &tail : dfs(end)) {
            res.push_back(tail.empty() ? w : w + " " + tail);
          }
        }
      }
      return memo[start] = res;
    };
    return dfs(0);
  }
};

func wordBreak(s string, wordDict []string) []string {
	dict := make(map[string]bool, len(wordDict))
	for _, w := range wordDict {
		dict[w] = true
	}
	memo := make(map[int][]string)
	var dfs func(start int) []string
	dfs = func(start int) []string {
		if v, ok := memo[start]; ok {
			return v
		}
		if start == len(s) {
			return []string{""}
		}
		var res []string
		for end := start + 1; end <= len(s); end++ {
			w := s[start:end]
			if dict[w] {
				for _, tail := range dfs(end) {
					if tail == "" {
						res = append(res, w)
					} else {
						res = append(res, w+" "+tail)
					}
				}
			}
		}
		memo[start] = res
		return res
	}
	res := dfs(0)
	if res == nil {
		return []string{}
	}
	return res
}

class Solution {
  public List<String> wordBreak(String s, List<String> wordDict) {
    Set<String> dict = new HashSet<>(wordDict);
    Map<Integer, List<String>> memo = new HashMap<>();
    return dfs(s, 0, dict, memo);
  }

  private List<String> dfs(String s, int start, Set<String> dict, Map<Integer, List<String>> memo) {
    if (memo.containsKey(start)) {
      return memo.get(start);
    }
    if (start == s.length()) {
      return new ArrayList<>(Arrays.asList(""));
    }
    List<String> res = new ArrayList<>();
    for (int end = start + 1; end <= s.length(); end++) {
      String w = s.substring(start, end);
      if (dict.contains(w)) {
        for (String tail : dfs(s, end, dict, memo)) {
          res.add(tail.isEmpty() ? w : w + " " + tail);
        }
      }
    }
    memo.put(start, res);
    return res;
  }
}

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        dict_set = set(wordDict)
        memo = {}

        def dfs(start):
            if start in memo:
                return memo[start]
            if start == len(s):
                return [""]
            res = []
            for end in range(start + 1, len(s) + 1):
                w = s[start:end]
                if w in dict_set:
                    for tail in dfs(end):
                        res.append(w if tail == "" else w + " " + tail)
            memo[start] = res
            return res

        return dfs(0)

use std::collections::{HashMap, HashSet};
impl Solution {
  fn dfs(
    start: usize,
    s: &str,
    dict: &HashSet<String>,
    memo: &mut HashMap<usize, Vec<String>>,
  ) -> Vec<String> {
    if let Some(v) = memo.get(&start) {
      return v.clone();
    }
    if start == s.len() {
      return vec![String::new()];
    }
    let mut res: Vec<String> = Vec::new();
    for end in (start + 1)..=s.len() {
      if !s.is_char_boundary(end) {
        continue;
      }
      let w = &s[start..end];
      if dict.contains(w) {
        for tail in Solution::dfs(end, s, dict, memo) {
          if tail.is_empty() {
            res.push(w.to_string());
          } else {
            res.push(format!("{} {}", w, tail));
          }
        }
      }
    }
    memo.insert(start, res.clone());
    res
  }

  pub fn word_break(s: String, word_dict: Vec<String>) -> Vec<String> {
    let dict: HashSet<String> = word_dict.into_iter().collect();
    let mut memo: HashMap<usize, Vec<String>> = HashMap::new();
    Solution::dfs(0, &s, &dict, &mut memo)
  }
}

const wordBreak = (s: string, wordDict: string[]): string[] => {
  const dict = new Set<string>(wordDict);
  const memo = new Map<number, string[]>();

  const dfs = (start: number): string[] => {
    if (memo.has(start)) {
      return memo.get(start)!;
    }
    if (start === s.length) {
      return [""];
    }
    const res: string[] = [];
    for (let end = start + 1; end <= s.length; end++) {
      const w = s.slice(start, end);
      if (dict.has(w)) {
        for (const tail of dfs(end)) {
          res.push(tail === "" ? w : `${w} ${tail}`);
        }
      }
    }
    memo.set(start, res);
    return res;
  };

  return dfs(0);
};
